#!/usr/bin/env python3
"""Read each probe case's native transcript: resolved model, recorded effort per assistant row, Ultracode reminder."""
import collections
import glob
import json
import os
import sys

BASE = "<scratch>"
PROJECTS = os.path.expanduser("~/.claude/projects")
rows = []
for line in open(os.path.join(BASE, "results.tsv")):
    name, case_dir = line.split()
    encoded = case_dir.replace("/", "-").replace("_", "-")
    matches = [d for d in glob.glob(os.path.join(PROJECTS, "*")) if os.path.basename(d) == encoded]
    if not matches:
        # the client may encode dots and other characters differently: fall back to a suffix match on the case name
        matches = [d for d in glob.glob(os.path.join(PROJECTS, "*")) if os.path.basename(d).endswith("case-" + name)]
    if not matches:
        rows.append((name, "NO TRANSCRIPT DIR", "", "", ""))
        continue
    files = sorted(glob.glob(os.path.join(matches[0], "*.jsonl")), key=os.path.getmtime)
    models, efforts, reminder, n = collections.Counter(), collections.Counter(), 0, 0
    for path in files[-1:]:
        for ln in open(path, errors="replace"):
            try:
                j = json.loads(ln)
            except ValueError:
                continue
            m = j.get("message") or {}
            if m.get("role") == "assistant":
                n += 1
                if m.get("model"):
                    models[m["model"]] += 1
                if "effort" in j:
                    efforts[str(j["effort"])] += 1
            if "Ultracode is on: optimize" in ln:
                reminder += 1
    rc = open(os.path.join(BASE, "rc-%s.txt" % name)).read().strip() if os.path.exists(os.path.join(BASE, "rc-%s.txt" % name)) else "?"
    rows.append((name, dict(models), dict(efforts), "reminder_lines=%d" % reminder, "%s assistant_rows=%d" % (rc, n)))
for r in rows:
    print(" | ".join(str(x) for x in r))

