#!/usr/bin/env python3
"""Second probe set: main-session model and effort, Ultracode reminder, and any subagent transcript's model and effort."""
import collections
import glob
import json
import os

BASE = "<scratch>"
PROJECTS = os.path.expanduser("~/.claude/projects")


def summarize(path):
    models, efforts, n, reminder = collections.Counter(), collections.Counter(), 0, 0
    for ln in open(path, errors="replace"):
        try:
            j = json.loads(ln)
        except ValueError:
            continue
        m = j.get("message") or {}
        if m.get("role") == "assistant":
            n += 1
            if m.get("model"):
                models[m["model"]] += 1
            if "effort" in j:
                efforts[str(j["effort"])] += 1
        if "Ultracode is on: optimize" in ln:
            reminder += 1
    return dict(models), dict(efforts), n, reminder


for line in open(os.path.join(BASE, "results2.tsv")):
    name, case_dir = line.split()
    encoded = case_dir.replace("/", "-").replace("_", "-")
    matches = [d for d in glob.glob(os.path.join(PROJECTS, "*")) if os.path.basename(d) == encoded] or \
              [d for d in glob.glob(os.path.join(PROJECTS, "*")) if os.path.basename(d).endswith("case-" + name)]
    rc_path = os.path.join(BASE, "rc-%s.txt" % name)
    rc = open(rc_path).read().strip() if os.path.exists(rc_path) else "?"
    if not matches:
        print(name, "| NO TRANSCRIPT DIR |", rc)
        continue
    mains = sorted(glob.glob(os.path.join(matches[0], "*.jsonl")), key=os.path.getmtime)
    main = summarize(mains[-1]) if mains else None
    subs = []
    for sub in glob.glob(os.path.join(matches[0], "*", "subagents", "agent-*.jsonl")):
        subs.append(summarize(sub)[:3])
    print(name, "| main:", main, "| subagents:", subs, "|", rc)
